def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    total_rounds = 100
    remaining = total_rounds - n

    # Extract opponent history once.
    # Recent window emphasis with fallback to full history for small n.
    if n >= 10:
        recent = history[-10:]
    else:
        recent = history

    opp_def_recent = 0
    for a, b in recent:
        if b == 'D':
            opp_def_recent += 1

    total_opp_def = 0
    for a, b in history:
        if b == 'D':
            total_opp_def += 1

    prior_own, prior_opp = history[-1]
    total_my_def = 0
    for a, b in history:
        if a == 'D':
            total_my_def += 1

    # If opponent has never defected, cooperate until it matters, then defect
    # at the final round to grab the extra 2 points.
    if total_opp_def == 0:
        return 'C' if remaining > 1 else 'D'

    # Near the endgame, exploit a mostly-cooperative opponent.
    if remaining <= 2:
        if total_opp_def <= 2:
            return 'D'
        return 'D' if prior_opp == 'D' else 'C'

    # Opponent just cooperated.
    if prior_opp == 'C':
        # If opponent has been very compliant recently, mostly cooperate.
        if opp_def_recent <= 1:
            return 'C'
        # Moderate recent defections: keep cooperating to repair the relationship.
        if opp_def_recent <= 3:
            return 'C'
        # Many recent defections: defect to avoid being exploited.
        return 'D'

    # Opponent just defected.
    # Look at opponent's defection streak at the tail.
    streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak += 1
        else:
            break

    # Long streak: keep retaliating.
    if streak >= 3:
        return 'D'

    # Recent opponent defection rate.
    opp_def_rate = total_opp_def / n

    # If opponent is rarely defecting overall, forgive once to escape DD spirals.
    if opp_def_rate <= 0.15:
        if prior_own == 'D' or streak >= 2:
            return 'D'
        return 'C'

    # Moderate defection rate: use proportional retaliation with slight forgiveness.
    if opp_def_rate <= 0.35:
        # If our own defection count is already high, break the cycle by cooperating.
        if total_my_def > total_opp_def + 1:
            return 'C'
        if streak >= 2:
            return 'D'
        return 'D' if rng.random() < 0.6 else 'C'

    # High defection rate: punish hard, occasionally probe.
    if opp_def_rate <= 0.7:
        if streak >= 2:
            return 'D'
        return 'D' if rng.random() < 0.85 else 'C'

    # Very defective opponent: defect consistently.
    return 'D'
